import{_ as t,o as a,c as s,a3 as r}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"Custom sidebar panels","description":"Create UIX sidebar links that redirect to any Home Assistant page.","frontmatter":{"description":"Create UIX sidebar links that redirect to any Home Assistant page."},"headers":[],"relativePath":"en/projects/uix/using/custom-sidebar-panels.md","filePath":"en/projects/uix/using/custom-sidebar-panels.md","lastUpdated":1793447386000}'),i={name:"en/projects/uix/using/custom-sidebar-panels.md"};function o(n,e,c,d,l,p){return a(),s("div",null,[...e[0]||(e[0]=[r('<blockquote><p>Adapted from the canonical English UIX documentation by <a href="https://github.com/Lint-Free-Technology/uix" target="_blank" rel="noreferrer">Lint-Free-Technology/uix</a>, <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noreferrer">CC BY 4.0</a>. Source: <code>dev</code> / <strong>9.0.0-beta.6</strong>, revision <a href="https://github.com/Lint-Free-Technology/uix/commit/e6fb84dd715ea4bac9a330357705897ea8d44690" target="_blank" rel="noreferrer">e6fb84d</a>, reviewed 31 October 2026. This source mirror may describe preview behavior beyond stable 8.4.0. Markup adapted for this site; the <a href="https://uix.lf.technology/" target="_blank" rel="noreferrer">original documentation</a> remains authoritative.</p></blockquote><h1 id="custom-sidebar-panels" tabindex="-1">Custom sidebar panels <a class="header-anchor" href="#custom-sidebar-panels" aria-label="Permalink to &quot;Custom sidebar panels&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Custom sidebar panel redirect’s available in 9.0.0-beta.6</p></div><p>UIX can add custom entries to the Home Assistant sidebar that redirect directly to another Home Assistant page. This is useful for frequently used pages that are normally nested under Settings or another panel.</p><p>Open <strong>Settings</strong> &gt; <strong>Devices &amp; services</strong> &gt; <strong>UI eXtension</strong> &gt; <strong>Configure</strong>, then select <strong>Manage custom sidebar panels</strong>. Add a panel by choosing its icon, entering its title, and selecting its target with the navigation selector.</p><p>Enable <strong>Admin required</strong> to restrict the sidebar panel to administrator accounts.</p><p>Targets are Home Assistant navigation paths and must remain within your Home Assistant instance; custom sidebar panels do not redirect to external sites.</p><p>Each panel has a stable internal URL managed by UIX, so you can change its title, icon, and target without recreating it. Deleting a panel immediately removes its sidebar entry.</p><div class="tip custom-block"><p class="custom-block-title">Sidebar order</p><p>Home Assistant lets each user <a href="https://www.home-assistant.io/dashboards/dashboards/#reorganizing-items-in-the-sidebar" target="_blank" rel="noreferrer">reorder and hide sidebar items</a> from their profile.</p></div><div class="info custom-block"><p class="custom-block-title">Redirect behaviour</p><p>A custom sidebar panel is a redirect, not a duplicate page. When selected, UIX replaces the panel URL with the configured target so browser history does not contain an extra redirect step.</p></div>',10)])])}const h=t(i,[["render",o]]);export{u as __pageData,h as default};
